    let canonical = op_state_store::schema_validator::canonicalize_json(value);
    simd_json::to_vec(&canonical).unwrap_or_else(|_| b"{}".to_vec())
}

pub fn sha256_hex(bytes: &[u8]) -> String {
    let mut hasher = Sha256::new();
    hasher.update(bytes);
    hex::encode(hasher.finalize())
}

pub fn to_pascal_ident(value: &str) -> String {
    let mut ident = String::new();
    let mut uppercase_next = true;
    for ch in value.chars() {
        if ch.is_ascii_alphanumeric() {
            if uppercase_next {
                ident.push(ch.to_ascii_uppercase());
                uppercase_next = false;
            } else {
                ident.push(ch);
            }
        } else {
            uppercase_next = true;
        }
    }
    if ident.is_empty() {
        "Generated".to_string()
    } else if ident
        .chars()
        .next()
        .is_some_and(|ch| ch.is_ascii_digit())
    {
        format!("P{}", ident)
    } else {
        ident
    }
}

pub fn sanitize_blob_component(value: &str) -> String {
    let mut sanitized = String::new();
    let mut previous_was_dash = false;
    for ch in value.chars() {
        if ch.is_ascii_alphanumeric() {
            sanitized.push(ch.to_ascii_lowercase());
            previous_was_dash = false;
        } else if !previous_was_dash {
            sanitized.push('-');
            previous_was_dash = true;
        }
    }
    sanitized
        .trim_matches('-')
        .chars()
        .collect::<String>()
        .if_empty_then("plugin")
}

pub fn sanitize_proto_ident(value: &str) -> String {
    let mut ident = String::new();
    for ch in value.chars() {
        if ch.is_ascii_alphanumeric() || ch == '_' {
            ident.push(ch);
        } else {
            ident.push('_');
        }
    }

    if ident.is_empty() {
        "field".to_string()
    } else if ident.chars().next().is_some_and(|ch| ch.is_ascii_digit()) {
        format!("_{ident}")
    } else {
        ident
    }
}

trait EmptyStringFallback {
    fn if_empty_then(self, fallback: &str) -> String;
}

impl EmptyStringFallback for String {
    fn if_empty_then(self, fallback: &str) -> String {
        if self.is_empty() {
            fallback.to_string()
        } else {
            self
        }
    }
}

